INSERT INTO dataset_metadata(version,datasetId,schemaVersion,generatedOn,verifiedOn,coverageFrom,coverageNote,demo,active,origin,importedAtMillis) VALUES (1,'pl-krajowe-wody-srodladowe',1,'2026-10-26','2026-10-26','2023-07-27','Przepisy krajowe dla powierzchniowych wód śródlądowych wg rozporządzenia Dz.U. 2023 poz. 1373 (stan sprawdzony 26.10.2026 w eli.gov.pl, nie znaleziono aktów zmieniających). Nie obejmuje regulaminów okręgów PZW ani innych gospodarzy wód, raków, wód morskich ani gatunków chronionych na podstawie ustawy o ochronie przyrody.',0,1,'sql',0);
INSERT INTO regulation_source(datasetVersion,id,title,reference,url,type,publishedOn,verifiedOn,notes) VALUES (1,'DzU-2023-1373','Rozporządzenie Ministra Rolnictwa i Rozwoju Wsi z dnia 12 lipca 2023 r. w sprawie szczegółowych warunków ochrony i połowu ryb w powierzchniowych wodach śródlądowych','Dz.U. 2023 poz. 1373','https://eli.gov.pl/eli/DU/2023/1373/ogl','LEGAL_ACT','2023-07-19','2026-10-26','Wejście w życie 27.07.2023. Wymiar ochronny: połów dozwolony powyżej wymiaru (§ 6 ust. 2); długość od początku zamkniętego pyska do końca najdłuższego promienia płetwy ogonowej. § 7 ust. 2: okres skraca się o pierwszy/ostatni dzień, jeśli przypada na dzień ustawowo wolny od pracy (nie dotyczy jesiotra ostronosego).');
INSERT INTO regulation_source(datasetVersion,id,title,reference,url,type,publishedOn,verifiedOn,notes) VALUES (1,'ustawa-dni-wolne','Ustawa z dnia 18 stycznia 1951 r. o dniach wolnych od pracy','Dz.U. 1951 nr 4 poz. 28 z późn. zm.',NULL,'LEGAL_ACT',NULL,'2026-10-26','Podstawa listy dni ustawowo wolnych (niedziele i święta; od 2025 r. także 24 grudnia) używanej przy § 7 ust. 2 rozporządzenia.');
INSERT INTO regulation_source(datasetVersion,id,title,reference,url,type,publishedOn,verifiedOn,notes) VALUES (1,'PZW-969-artykul','PZW – Wymiary i okresy ochronne poszczególnych gatunków ryb (artykuł)','artykuł na stronie 969.pzw.pl','https://969.pzw.pl/szczegoly-artykulu/wymiary-i-okresy-ochronne-poszczegolnych-gatunkow-ryb_JxSoP0LtQtcT711JFCPX','SECONDARY',NULL,NULL,'Strona blokuje automatyczne pobieranie (robots.txt). Nie posłużyła jako podstawa żadnej reguły; reguły pochodzą wprost z rozporządzenia.');
